        let storage = ExposedDataPipeline::new_with_ingestion_key(
            &temporary.path().join("data"),
            IngestionKey::default(),
        )?;
        let member = MemberAsId::new(Uuid::from_u128(1), 4613)?;
        let fetched_at = Utc::now();
        let declarations = [
            ("Unite Union", "Trade Union", ""),
            ("Unite West Midlands", "Trade Union", ""),
            ("HSBC UK (Ian Stuart, CEO)", "Company", "1 Centenary Square Birmingham B1 1HQ"),
            ("HSBC UK Bank plc", "Company", "1 Centenary Square Birmingham B1 1HQ"),
            ("HSBC UK Bank plc", "Company", "1 Centenary Square Birmingham B1 1HQ"),
        ]
        .into_iter()
        .enumerate()
        .map(|(index, (name, kind, address))| {
            super::super::declaration_source::replay_declaration(json!({
                "id": index + 1,
                "category": {"id": 3, "name": "Donations"},
                "versions": [{"register": {"id": 820, "publishedDate": "2026-09-07"}, "fields": [
                    {"name": "DonorName", "value": name},
                    {"name": "DonorStatus", "value": kind},
                    {"name": "DonorPublicAddress", "value": address},
                    {"name": "Value", "value": "20"}
                ]}]
            }), fetched_at).map(|evidence| evidence.declaration().clone())
        })
        .collect::<Result<Vec<CapturedDeclaration>, _>>()?;
        storage.write_raw_declarations(member, &declarations).await?;
        DeclarationCleanerService::new(storage.clone()).clean_declarations().await?;
        DeclarationResolverService::new(storage.clone(), TestScorer(probability), 100)
            .resolve_declarations().await?;

        let resolved = storage.resolved_declarations_path();
        let identity_path = resolved.join("observation_resolution.parquet");
        let pair_path = resolved.join("pair_decisions.parquet");
        let (identities, _) = read_table::<serde_json::Value>(
            &identity_path, &declaration_resolution::observation_schema(),
        )?;
        let (pairs, _) = read_table::<serde_json::Value>(
            &pair_path, &declaration_resolution::pair_schema(),
        )?;
        for basis in ["trade_union_family_link", expected_basis] {
            assert!(identities.iter().any(|row| row["identity_basis"] == basis), "missing {basis}");
        }
        for reason in ["trade_union_family", "extracted_name_evidence"] {
            assert!(pairs.iter().any(|row| row["reason"] == reason), "missing {reason}");
        }
        let load = storage.read_declaration_load().await?;
        assert_eq!(load.funders.len(), 2);
        assert_eq!(load.funding_entries.len(), 5);
        for ids in [&[1, 2][..], &[3, 4, 5][..]] {
            let identities = load.funding_entries.iter()
                .filter(|entry| ids.contains(&entry.source_declaration_id))
                .map(|entry| entry.identity_id.as_ref().expect("resolved funder"))
                .collect::<BTreeSet<_>>();
            assert_eq!(identities.len(), 1);
        }

        for (path, schema, rows, field, expected_error) in [
            (&identity_path, declaration_resolution::observation_schema(), &identities,
             "identity_basis", "invalid or duplicate resolved observation identity"),
            (&pair_path, declaration_resolution::pair_schema(), &pairs,
             "reason", "invalid resolved pair decision"),
        ] {
            let mut malformed = rows.clone();
            malformed[0][field] = json!("unknown_resolution_label");
            declaration_cleaning::write_table(path, schema.clone(), &malformed).await?;
            let error = storage.read_declaration_load().await.err().expect("unknown label rejected");
            assert!(error.to_string().contains(expected_error), "{error}");
            declaration_cleaning::write_table(path, schema, rows).await?;
        }
    }
    Ok(())
}

